from fastapi import FastAPI, Response, Cookie
from fastapi.responses import JSONResponse

app = FastAPI()

VALID_SESSIONS = {"sess-abc": "user1"}

@app.post('/items')
def add_item(payload: dict, response: Response, session_id: str | None = Cookie(default=None)):
    user = VALID_SESSIONS.get(session_id or "")
    if not user:
        return JSONResponse(status_code=401, content={'error': 'unauthorized'})
    if not payload.get('name'):
        return JSONResponse(status_code=400, content={'error': 'missing name'})
    response.headers['Location'] = f"/items/{payload['name']}"
    return JSONResponse(status_code=201, content={'name': payload['name']})

